// Deterministic "Daily Challenge" + elimination (KO) scheduling rules.
// Pure and engine independent: the browser bundle is generated by ../build.js.

/** FNV-1a — stable across runs and platforms, so every player gets the same daily event. */
export function hashSeed(s: string): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

/** Small fast PRNG, returns a function producing floats in [0,1). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// A daily challenge must be identical for every player, so "dyn" (mid-race random weather) is excluded.
export const WEATHERS = ['clear', 'rain', 'fog'];
export const TIMES = ['day', 'sunset', 'night'];

export interface DailyConfig {
  day: string; car: number; loc: number; laps: number;
  wx: string; tod: string; diff: number; target: number;
}

/**
 * The challenge of the day. Same `day` string -> same event for everybody.
 * `target` is the par time (seconds) to beat for the completion bonus.
 */
export function dailyChallenge(day: string, carCount = 12, locCount = 6): DailyConfig {
  const r = mulberry32(hashSeed('vx-daily|' + day));
  const car = Math.floor(r() * carCount);
  const loc = Math.floor(r() * locCount);
  const laps = 2 + Math.floor(r() * 3);
  const wx = WEATHERS[Math.floor(r() * WEATHERS.length)];
  const tod = TIMES[Math.floor(r() * TIMES.length)];
  const diff = 2 + Math.floor(r() * 4);
  // ~40 s per lap on the tight tracks, a little more on the long ones, more rain = more slack.
  const target = Math.round((laps * 41 + loc * 1.5 + (wx === 'rain' ? 6 : wx === 'fog' ? 4 : 0)) * 10) / 10;
  return { day, car, loc, laps, wx, tod, diff, target };
}

/** Absolute race-clock times at which the last car is knocked out (`rounds` = cars - 1). */
export function eliminationTimes(startAt: number, interval: number, rounds: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < rounds; i++) out.push(Math.round((startAt + interval * i) * 100) / 100);
  return out;
}

export const KO_START = 15, KO_INTERVAL = 20;
